        $message .= '-----------------------' . "\n";
        $message .= $this->userlink . "\n";
        $message .= '-----------------------' . "\n";
        $message .= _t('LOGIN_THE_TEAM') . ' ' . $domain . "\n";

        $subject = $title . ' ' . $domain;
        // Send the email
