	if be, err := annotationBackend(i.Metadata); err != nil {
		return
	} else {
		switch be {
		case eskip.ForwardBackend:
			r.BackendType = eskip.NetworkBackend
			r.Backend = ing.forwardBackendURL
			r.Filters = []*eskip.Filter{}
