    @Converter
    public static byte[] toByteArray(IoBuffer buffer) {
        byte[] answer = new byte[buffer.remaining()];
        buffer.get(answer);
        return answer;
        // we should not mark and reset the buffer with mina
    }

    @Converter
    public static String toString(IoBuffer buffer, Exchange exchange) {
        byte[] bytes = toByteArray(buffer);
        // use type converter as it can handle encoding set on the Exchange
        return exchange.getContext().getTypeConverter().convertTo(String.class, exchange, bytes);
    }

    @Converter
    public static InputStream toInputStream(IoBuffer buffer) {
        return buffer.asInputStream();
    }

    @Converter
    public static ObjectInput toObjectInput(IoBuffer buffer) throws IOException {
        InputStream is = toInputStream(buffer);
        ObjectInputStream ois = new ObjectInputStream(is);
        ObjectInputFilter jvmFilter = ObjectInputFilter.Config.getSerialFilter();
        if (jvmFilter != null) {
            ois.setObjectInputFilter(jvmFilter);
        } else {
            LOG.debug("No JVM-wide deserialization filter set, applying default Camel filter: {}",
                    DEFAULT_DESERIALIZATION_FILTER);
            ois.setObjectInputFilter(ObjectInputFilter.Config.createFilter(DEFAULT_DESERIALIZATION_FILTER));
        }
        return ois;
    }

    @Converter
    public static IoBuffer toIoBuffer(byte[] bytes) {
        IoBuffer buf = IoBuffer.allocate(bytes.length);
        buf.put(bytes);
        return buf;
    }

    @Converter
    public static IoBuffer toIoBuffer(StreamCache cache, Exchange exchange) throws Exception {
        byte[] arr = exchange.getContext().getTypeConverter().mandatoryConvertTo(byte[].class, exchange, cache);
        return toIoBuffer(arr);
    }
}

