const {Mollie} = window;

document.addEventListener('DOMContentLoaded', function () {
    const mollieData = document.querySelector('.online-online-payment__container');
    if (!mollieData) {
        return;
    }

    let disableValidationMollieComponents = false;
    let selectedValue = false;
    let orderId = null;
