	var err error
	for _, p := range path {
		_, err = os.Stat(p)
		if err == nil {
			return p, nil
		}
	}
	return "", err
}

// HasPrefix checks a path has a prefix, making sure to respect path boundaries. So that /aa & /a does not match, but /a/a & /a does.
