  ).then(res => getSizeCountWin(res.stdout))
}

function getFolderSize (folderPath) {
  if (isWin) {
    return getFolderSizeWin(folderPath)
  }
  return run(`du -sh "${folderPath}" && find "${folderPath}" -type f | wc -l`)
    .then(getSizeCount)
}

/**
