	return b.buildQuery("migration_issues_query", mustGetTemplate("migration_issues_query"), params)
}

// ResourceBreakdownsQuery builds the resource breakdowns query.
func (b *QueryBuilder) ResourceBreakdownsQuery(filters Filters) (string, error) {
	params := queryParams{
		ClusterFilter: escapeSQLString(filters.Cluster),
		VMListFilter:  buildVMListFilter(filters.VMList, "i"),
	}
	return b.buildQuery("resource_breakdowns_query", mustGetTemplate("resource_breakdowns_query"), params)
}

// AboutQuery builds the query for the single `about` table row (API/product/uuid).
func (b *QueryBuilder) AboutQuery() (string, error) {
	return b.buildQuery("about_query", mustGetTemplate("about_query"), nil)
}

// VMsWithSharedDisksCountQuery builds the VMs with shared disks count query.
func (b *QueryBuilder) VMsWithSharedDisksCountQuery(filters Filters) (string, error) {
	params := queryParams{
		ClusterFilter: escapeSQLString(filters.Cluster),
		VMListFilter:  buildVMListFilter(filters.VMList, "i"),
	}
	return b.buildQuery("vms_with_shared_disks_count_query", mustGetTemplate("vms_with_shared_disks_count_query"), params)
}

// generateOSCaseClauses reads complexity.OSDifficultyScores and generates SQL WHEN clauses.
func generateOSCaseClauses() string {
	scoreToLevel := map[int]string{
		1: "easy",
		2: "medium",
		3: "hard",
		4: "database",
	}
	var clauses []string
	for keyword, score := range complexity.OSDifficultyScores {
		level := scoreToLevel[score]
		clauses = append(clauses, fmt.Sprintf(
			"            WHEN LOWER(effective_os) LIKE '%%%s%%' THEN '%s'", strings.ToLower(keyword), level))
	}
	sort.Strings(clauses) // deterministic output
	return strings.Join(clauses, "\n")
}

// generateComplexityMatrixCaseClauses reads complexity.ComplexityMatrix and generates
// SQL WHEN clauses for the combined OS+disk complexity CASE expression.
func generateComplexityMatrixCaseClauses() string {
	osScoreToLevel := map[complexity.Score]string{
		0: "unsupported",
		1: "easy",
		2: "medium",
		3: "hard",
		4: "database",
	}
	diskScoreToLevel := map[complexity.Score]string{
		1: "easy",
		2: "medium",
		3: "hard",
		4: "whiteglove",
	}

	// Collect and sort outer (OS) keys for deterministic output.
	osKeys := make([]complexity.Score, 0, len(complexity.ComplexityMatrix))
	for osScore := range complexity.ComplexityMatrix {
		osKeys = append(osKeys, osScore)
	}
	sort.Ints(osKeys)

	var clauses []string
	for _, osScore := range osKeys {
		inner := complexity.ComplexityMatrix[osScore]
		osLevel := osScoreToLevel[osScore]

		// Collect and sort inner (disk) keys for deterministic output.
		diskKeys := make([]complexity.Score, 0, len(inner))
		for diskScore := range inner {
			diskKeys = append(diskKeys, diskScore)
		}
		sort.Ints(diskKeys)

		for _, diskScore := range diskKeys {
			combined := inner[diskScore]
			diskLevel := diskScoreToLevel[diskScore]
			clauses = append(clauses, fmt.Sprintf(
				"            WHEN o.os_level = '%s' AND dl.disk_level = '%s' THEN %d",
				osLevel, diskLevel, combined))
		}
	}
	return strings.Join(clauses, "\n")
}

// PopulateComplexityQuery returns a query that computes and stores per-VM migration complexity.
func (b *QueryBuilder) PopulateComplexityQuery() (string, error) {
	params := queryParams{
		OSCaseClauses:           generateOSCaseClauses(),
		ComplexityMatrixClauses: generateComplexityMatrixCaseClauses(),
	}
	return b.buildQuery("populate_complexity", mustGetTemplate("populate_complexity"), params)
}

// buildVMListFilter creates a SQL IN clause for filtering by VM IDs.
// Returns an empty string if the VMList is empty.
// tableAlias is the optional table alias (e.g., "i") - use empty string for no alias.
func buildVMListFilter(vmList []string, tableAlias string) string {
	if len(vmList) == 0 {
		return ""
	}

	// Escape and quote each VM ID
	quoted := make([]string, len(vmList))
	for i, vmID := range vmList {
		// Escape single quotes by doubling them
		escaped := strings.ReplaceAll(vmID, "'", "''")
		quoted[i] = fmt.Sprintf("'%s'", escaped)
	}

	// Build column reference with or without alias
	columnRef := "\"VM ID\""
	if tableAlias != "" {
		columnRef = fmt.Sprintf("%s.\"VM ID\"", tableAlias)
	}

	return fmt.Sprintf(" AND %s IN (%s)", columnRef, strings.Join(quoted, ", "))
}

func (b *QueryBuilder) buildQuery(name, tmplContent string, params any) (string, error) {
	tmpl, err := template.New(name).Parse(tmplContent)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, params); err != nil {
		return "", err
	}
	return strings.TrimSpace(buf.String()), nil
}

